import {OfflineVoice} from './speech.js';
export const GESTURES={Closed_Fist:'left',Victory:'right',Thumb_Up:'forward',Thumb_Down:'back',Open_Palm:'stop',Pointing_Up:'interact',ILoveYou:'jump'};
const VOICE_MAP={'влево':'left','налево':'left','вправо':'right','направо':'right','вперед':'forward','назад':'back','стой':'stop','стоп':'stop','остановись':'stop','прыжок':'jump','прыгни':'jump','действие':'interact','взаимодействовать':'interact','пауза':'pause','продолжить':'resume','подсказка':'hint','журнал':'journal','первый вариант':'choice1','вариант один':'choice1','второй вариант':'choice2','вариант два':'choice2','третий вариант':'choice3','вариант три':'choice3','поддержать сергея':'empathize','спросить сергея':'ask','показать свидетельства':'evidence','начать':'start','повторить':'retry','сменить вид':'view','прибор':'travel','проверить цепь':'circuit-check','проверить':'circuit-check','камера влево':'look-left','камера вправо':'look-right','камера вверх':'look-up','камера вниз':'look-down','камера стоп':'look-stop','посмотри влево':'look-left','посмотри вправо':'look-right','посмотри вверх':'look-up','посмотри вниз':'look-down'};
const VOICE_KEYS=Object.keys(VOICE_MAP).sort((a,b)=>b.length-a.length);
export function voiceCommand(text){const t=String(text).toLowerCase().replace(/ё/g,'е').replace(/[.,!?;:]/g,'').replace(/\s+/g,' ').trim().replace(/^(анна |пожалуйста |иди |шаг )+/g,'');if(VOICE_MAP[t])return VOICE_MAP[t];for(const key of VOICE_KEYS)if(t.includes(key))return VOICE_MAP[key];return null;}
export class GestureGate{
 constructor(hold=160){this.hold=hold;this.label=null;this.since=0;this.fired=false;this.motion='stop';this.lastGood=0;}
 update(label,score,time,present=true){const known=!!GESTURES[label]&&score>=.65;if(!present||!known){if(present&&this.motion!=='stop'&&time-this.lastGood<250)return {motion:this.motion,action:null};this.label=null;this.fired=false;this.motion='stop';return {motion:'stop',action:null};}if(this.label!==label){this.label=label;this.since=time;this.fired=false;}this.lastGood=time;if(label==='Open_Palm'){const action=this.fired?null:'stop';this.fired=true;this.motion='stop';return {motion:'stop',action};}const arm=['Pointing_Up','ILoveYou'].includes(label)?280:this.hold;if(time-this.since<arm)return {motion:this.motion==='stop'?'stop':this.motion,action:null};const cmd=GESTURES[label],action=this.fired?null:cmd;this.fired=true;this.motion=['left','right','forward','back'].includes(cmd)?cmd:'stop';return {motion:this.motion,action};}
 reset(){this.label=null;this.fired=false;this.motion='stop';this.lastGood=0;}
}
export class TwoHandController{
 constructor(){this.movement=new GestureGate();this.camera=new GestureGate();}
 reset(){this.movement.reset();this.camera.reset();}
 update(hands,time,movementHand='Left'){
  const cameraHand=movementHand==='Left'?'Right':'Left';
  const choose=side=>(hands||[]).filter(h=>h.handedness===side&&h.handednessScore>=.55).sort((a,b)=>b.score-a.score)[0];
  const m=choose(movementHand),c=choose(cameraHand);
  const move=this.movement.update(m?.label,m?.score||0,time,!!m),look=this.camera.update(c?.label,c?.score||0,time,!!c);
  return {move,look:{x:look.motion==='left'?-1:look.motion==='right'?1:0,y:look.motion==='forward'?-1:look.motion==='back'?1:0},movementLabel:m?.label||null,cameraLabel:c?.label||null,movementHand,cameraHand};
 }
}
export class Controls{
 constructor(onAction,onStatus){this.onAction=onAction;this.onStatus=onStatus;this.keys=new Set();this.voiceMotion=null;this.voiceUntil=0;this.gestureMotion=null;this.hands=new TwoHandController();this.gate=this.hands.movement;this.movementHand=localStorage.getItem('station17-movement-hand')==='Right'?'Right':'Left';this.gestureLook={x:0,y:0};this.gestureLookUntil=0;this.voiceLook={x:0,y:0};this.voiceLookUntil=0;this.generation=0;this.speech=null;this.listening=false;this.cameraOn=false;this.worker=null;this.stream=null;this.framePending=false;this.lastFrame=0;
  addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;if([' ','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))e.preventDefault();this.keys.add(e.key.toLowerCase());if(e.repeat)return;const cmd={' ':'jump',e:'interact',Escape:'pause',j:'journal',h:'hint','1':'choice1','2':'choice2','3':'choice3','4':'choice4','5':'choice5','6':'choice6','7':'choice7','8':'choice8','9':'choice9',m:'microphone',g:'gestures',v:'view',r:'travel',f:'circuit-check',Enter:'confirm'}[e.key.length===1?e.key.toLowerCase():e.key]||{'у':'interact','о':'journal','р':'hint','м':'view','к':'travel','а':'circuit-check','ь':'microphone','п':'gestures'}[e.key.toLowerCase()];if(cmd){if(cmd==='confirm')e.preventDefault();this.onAction(cmd,'keyboard');}});
  addEventListener('keyup',e=>this.keys.delete(e.key.toLowerCase()));addEventListener('blur',()=>this.resetMotion());document.addEventListener('visibilitychange',()=>{if(document.hidden){this.resetMotion();this.stopVoice();this.stopCamera();}});
 }
 motion(){if(this.keys.size){const x=Number(this.keys.has('d')||this.keys.has('в')||this.keys.has('arrowright'))-Number(this.keys.has('a')||this.keys.has('ф')||this.keys.has('arrowleft'));const z=Number(this.keys.has('s')||this.keys.has('ы')||this.keys.has('arrowdown'))-Number(this.keys.has('w')||this.keys.has('ц')||this.keys.has('arrowup'));if(x||z)return {x,z,source:'keyboard'};}const now=performance.now(),voiceOn=!!this.voiceMotion&&this.voiceMotion!=='stop'&&now<this.voiceUntil,gestureOn=!!this.gestureMotion&&this.gestureMotion!=='stop'&&now<this.gestureLookUntil;if(this.cameraOn&&gestureOn)return {x:this.gestureMotion==='left'?-1:this.gestureMotion==='right'?1:0,z:this.gestureMotion==='forward'?-1:this.gestureMotion==='back'?1:0,source:'gesture'};if(voiceOn)return {x:this.voiceMotion==='left'?-1:this.voiceMotion==='right'?1:0,z:this.voiceMotion==='forward'?-1:this.voiceMotion==='back'?1:0,source:'voice'};return {x:0,z:0,source:'gesture'};}
 lookMotion(){const now=performance.now();if(now<this.voiceLookUntil)return this.voiceLook;if(this.cameraOn&&now<this.gestureLookUntil)return this.gestureLook;return {x:0,y:0};}
 swapHands(){this.movementHand=this.movementHand==='Left'?'Right':'Left';localStorage.setItem('station17-movement-hand',this.movementHand);this.hands.reset();this.resetMotion();this.showHandRoles();}
 showHandRoles(){const r=document.getElementById('gesture-roles');if(r)r.textContent=this.movementHand==='Left'?'Левая — персонаж · правая — камера':'Правая — персонаж · левая — камера';}
 resetMotion(){this.gestureLook={x:0,y:0};this.gestureLookUntil=0;this.voiceLookUntil=0;this.keys.clear();this.voiceMotion=null;this.voiceUntil=0;this.gestureMotion=null;}
 command(cmd,source){if(cmd.startsWith('look-')){this.voiceLook={x:cmd==='look-left'?-1:cmd==='look-right'?1:0,y:cmd==='look-up'?-1:cmd==='look-down'?1:0};this.voiceLookUntil=cmd==='look-stop'?0:performance.now()+1600;this.onAction(cmd,source);return;}if(cmd==='stop'&&source==='voice'){this.voiceLookUntil=0;this.gestureLook={x:0,y:0};}if(cmd==='stop'){this.voiceUntil=0;this.voiceMotion=null;this.gestureMotion=null;}if(['left','right','forward','back','stop'].includes(cmd)){if(source==='voice'&&cmd!=='stop'){this.voiceMotion=cmd;this.voiceUntil=performance.now()+600000;}this.onAction('navigate-'+cmd,source);}else this.onAction(cmd,source);}
 voiceSupported(){return !!(window.AudioContext&&window.WebAssembly&&navigator.mediaDevices?.getUserMedia);}
 async toggleVoice(){if(this.speech){this.stopVoice();return;}if(!this.voiceSupported()){this.onStatus('voice','Для голоса нужны современный браузер и адрес localhost или HTTPS.',false);return;}const voice=new OfflineVoice((text,confidence,partial)=>{const cmd=voiceCommand(text);if(partial&&!cmd)return;const now=performance.now();if(cmd&&cmd===this.lastVoiceCmd&&now-(this.lastVoiceAt||0)<700)return;if(cmd){this.lastVoiceCmd=cmd;this.lastVoiceAt=now;}this.onStatus('voice',cmd?'Услышано: '+text:'Команда не распознана: '+text,true);if(cmd)this.command(cmd,'voice');},(text,listening)=>{if(this.speech!==voice)return;this.listening=listening;if(!listening&&(text.startsWith('Голос недоступен')||text.startsWith('Разрешите')))this.speech=null;this.onStatus('voice',text,listening||text.startsWith('Загружается'));});this.speech=voice;await voice.start();}
 stopVoice(){const voice=this.speech;if(voice)voice.stop();this.speech=null;this.listening=false;this.voiceUntil=0;this.voiceLookUntil=0;this.onStatus('voice','Микрофон выключен.',false);}
 async toggleCamera(){if(this.cameraOn||this.worker){this.stopCamera();return;}const gen=++this.generation;this.onStatus('gesture','Загрузка модели жестов…',true);const panel=document.getElementById('camera-panel');panel.hidden=false;this.showHandRoles();
  try{
   if(!navigator.mediaDevices?.getUserMedia)throw new Error('Камера доступна только на localhost или HTTPS.');
   const worker=new Worker('/gesture-worker.js');this.worker=worker;
   await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error('Модель не успела загрузиться. Попробуйте ещё раз.')),30000);worker.onmessage=e=>{if(e.data.type==='ready'){clearTimeout(timer);resolve();}else if(e.data.type==='error'){clearTimeout(timer);reject(new Error(e.data.message));}};worker.onerror=e=>{clearTimeout(timer);reject(new Error(e.message));};worker.postMessage({type:'init'});});
   if(gen!==this.generation)return;
   const stream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:640},height:{ideal:480},facingMode:'user'},audio:false});
   if(gen!==this.generation){stream.getTracks().forEach(t=>t.stop());return;}this.stream=stream;const video=document.getElementById('camera');video.srcObject=stream;await video.play();this.cameraOn=true;this.onStatus('gesture','Покажите обе руки. Одной двигайтесь, второй вращайте камеру.',true);
   worker.onmessage=e=>{if(gen!==this.generation)return;if(e.data.type==='result'){this.framePending=false;const now=performance.now(),out=this.hands.update(e.data.hands||[],now,this.movementHand);this.gestureMotion=out.move.motion;if(out.move.action)this.command(out.move.action,'gesture');this.gestureLook=out.look;this.gestureLookUntil=now+700;this.onStatus('gesture','Персонаж: '+this.labelName(out.movementLabel)+' · Камера: '+this.cameraLabelName(out.cameraLabel),true);}else if(e.data.type==='error'){this.framePending=false;this.stopCamera();this.onStatus('gesture',e.data.message,false);}};
   const loop=async now=>{if(gen!==this.generation||!this.cameraOn)return;requestAnimationFrame(loop);if(this.framePending||now-this.lastFrame<110||video.readyState<2)return;this.lastFrame=now;this.framePending=true;try{const image=await createImageBitmap(video);if(gen!==this.generation){image.close();return;}worker.postMessage({type:'frame',image,time:now},[image]);}catch(e){this.framePending=false;}};requestAnimationFrame(loop);
  }catch(e){if(gen===this.generation){this.stopCamera();this.onStatus('gesture','Жесты недоступны: '+e.message,false);}}
 }
 cameraLabelName(s){return {Closed_Fist:'влево',Victory:'вправо',Thumb_Up:'вверх',Thumb_Down:'вниз',Open_Palm:'стоп',Pointing_Up:'стоп',ILoveYou:'стоп'}[s]||'рука не видна';}
 labelName(s){return {Closed_Fist:'Кулак — влево',Victory:'Два пальца — вправо',Thumb_Up:'Большой палец вверх — вперёд',Thumb_Down:'Большой палец вниз — назад',Open_Palm:'ладонь — стоп',Pointing_Up:'Указательный палец — действие',ILoveYou:'Мизинец и указательный — прыжок',None:'Жест не распознан'}[s]||'рука не видна';}
 stopCamera(){this.generation++;this.cameraOn=false;this.gestureMotion=null;this.gestureLook={x:0,y:0};this.gestureLookUntil=0;this.hands.reset();if(this.worker){this.worker.terminate();this.worker=null;}if(this.stream){this.stream.getTracks().forEach(t=>t.stop());this.stream=null;}const v=document.getElementById('camera');if(v){v.srcObject=null;document.getElementById('camera-panel').hidden=true;}this.framePending=false;this.onStatus('gesture','Камера выключена.',false);}
}
